"""Mantle-specific defaults for the shared privacy pipeline."""

from __future__ import annotations

from typing import TYPE_CHECKING, AbstractSet, Any, Dict, List, Optional

from pydantic import BaseModel, ConfigDict

from rasa.mantle.config.agent_privacy import (
    RULES_KEY,
    mantle_privacy_rules_rejected_message,
    tracker_store_settings_from_privacy,
)
from rasa.mantle.memory.field import MemoryField
from rasa.mantle.memory.manager import PROJECT_NAMESPACE
from rasa.privacy.privacy_config import (
    AnonymizationMethod,
    AnonymizationType,
    PrivacyConfig,
    TrackerStoreSettings,
    validate_sensitive_slots,
)
from rasa.privacy.privacy_filter import PrivacyFilter
from rasa.shared.core.constants import SESSION_START_METADATA_SLOT
from rasa.shared.exceptions import RasaException

if TYPE_CHECKING:
    from rasa.mantle.model_archive.bootstrap import ModelBootstrap
    from rasa.shared.core.domain import Domain

_DEFAULT_MASK = AnonymizationMethod(
    method_type=AnonymizationType.MASK,
    redaction_char="*",
)


def _iter_pii_memory_fields(
    bootstrap: "ModelBootstrap",
) -> List[tuple[str, MemoryField]]:
    """Return ``(slot name, field)`` for memory fields marked ``pii: true``."""
    fields: List[tuple[str, MemoryField]] = []
    for entry_name, field in bootstrap.project_memory.fields.items():
        if field.pii:
            fields.append((f"{PROJECT_NAMESPACE}.{entry_name}", field))
    for skill in bootstrap.skill_catalog.skills.values():
        for entry_name, field in skill.memory.definition.all_fields().items():
            if field.pii:
                fields.append((f"{skill.id}.{entry_name}", field))
    return fields


def collect_pii_memory_slot_names(bootstrap: "ModelBootstrap") -> List[str]:
    """Return tracker slot names for Mantle memory fields marked ``pii: true``."""
    return [slot_name for slot_name, _field in _iter_pii_memory_fields(bootstrap)]


def _anonymization_method_for_field(field: MemoryField) -> AnonymizationMethod:
    """Return the field's method, or whole-value mask when it omits one."""
    spec = field.anonymization
    if spec is None:
        return _DEFAULT_MASK
    return AnonymizationMethod(
        method_type=AnonymizationType(spec.type),
        redaction_char=spec.redaction_char,
        keep_left=spec.keep_left,
        keep_right=spec.keep_right,
    )


def anonymize_memory_field_value(field: MemoryField, slot_name: str, value: Any) -> Any:
    """Return *value*, anonymized when *field* is marked ``pii``.

    A PII field with no method is masked to ``[SLOT_NAME]``, the same default
    published events use. ``None`` stays unset. Every other value, including
    ``0`` and ``False``, is anonymized: those are real writes.
    """
    if not field.pii or value is None:
        return value
    method = _anonymization_method_for_field(field)
    if method.method_type == AnonymizationType.MASK:
        return PrivacyFilter._mask(slot_name)
    return PrivacyFilter._redact(value, method)


def pii_field_anonymization_rules(
    bootstrap: "ModelBootstrap",
) -> Dict[str, AnonymizationMethod]:
    """Map each PII memory slot to the anonymization method declared on it."""
    return {
        slot_name: _anonymization_method_for_field(field)
        for slot_name, field in _iter_pii_memory_fields(bootstrap)
    }


def mantle_builtin_protected_slot_names() -> List[str]:
    """Built-in Mantle slot names that must be masked on published events."""
    return [SESSION_START_METADATA_SLOT]


def merge_mantle_default_anonymization_rules(
    field_rules: Dict[str, AnonymizationMethod],
) -> Dict[str, AnonymizationMethod]:
    """Add the session-metadata mask without overriding field methods.

    Session-start metadata must use mask (whole-value replacement). Character
    redaction assumes a string value and fails on the call-metadata object.
    """
    if SESSION_START_METADATA_SLOT in field_rules:
        method = field_rules[SESSION_START_METADATA_SLOT]
        if method.method_type != AnonymizationType.MASK:
            raise RasaException(
                "Privacy rule for session_started_metadata must use anonymization "
                "type 'mask'. Redact is not supported for session-start metadata."
            )

    merged = dict(field_rules)
    for slot_name in mantle_builtin_protected_slot_names():
        merged.setdefault(slot_name, _DEFAULT_MASK)
    return merged


def mantle_slots_exempt_from_domain_validation(
    pii_memory_slot_names: List[str],
) -> AbstractSet[str]:
    """Slot names that may appear in privacy rules but not in a classic domain."""
    return frozenset(mantle_builtin_protected_slot_names() + pii_memory_slot_names)


class MantlePrivacySettings(BaseModel):
    """Privacy settings of one Mantle model, prepared before it serves traffic.

    ``config`` and ``privacy_filter`` are ``None`` when the agent has no
    ``privacy`` block.
    """

    model_config = ConfigDict(arbitrary_types_allowed=True, frozen=True)

    config: Optional[PrivacyConfig] = None
    privacy_filter: Optional[PrivacyFilter] = None


def _tracker_store_settings(
    privacy: Optional[Dict[str, Any]],
) -> Optional[TrackerStoreSettings]:
    """Return tracker-store cron settings from a Mantle ``privacy`` block."""
    if privacy is None:
        return None
    if RULES_KEY in privacy:
        raise RasaException(mantle_privacy_rules_rejected_message())
    return tracker_store_settings_from_privacy(privacy)


def build_mantle_privacy_settings(
    bootstrap: "ModelBootstrap", domain: "Domain"
) -> MantlePrivacySettings:
    """Build and validate the privacy settings of a loaded Mantle agent.

    Anonymization methods come from ``pii: true`` memory fields. The
    ``privacy`` block in ``agent.yml``, when present, supplies tracker-store
    cron settings only. Session-start metadata is masked whenever either is
    set.

    Raises:
        RasaException: If ``privacy`` still contains ``rules``, or a rule
            targets a slot that is neither in the domain nor a Mantle PII
            memory field.
    """
    field_rules = pii_field_anonymization_rules(bootstrap)
    if bootstrap.privacy is None and not field_rules:
        return MantlePrivacySettings()

    tracker_store_settings = _tracker_store_settings(bootstrap.privacy)
    pii_slot_names = list(field_rules)
    anonymization_rules = merge_mantle_default_anonymization_rules(field_rules)
    validate_sensitive_slots(
        list(anonymization_rules),
        domain,
        slots_without_domain_entry=mantle_slots_exempt_from_domain_validation(
            pii_slot_names
        ),
    )
    config = PrivacyConfig(
        anonymization_rules=anonymization_rules,
        tracker_store_settings=tracker_store_settings,
    )
    return MantlePrivacySettings(
        config=config,
        privacy_filter=PrivacyFilter(config.anonymization_rules),
    )
